infraDomain('platform').refs=[...new Set([...infraDomain('platform').refs,'v22Quant','v22Dequant','v22TorchQuant','v22GPTQ','v22AWQ','v22Smooth','v22QLoRA','v22Speculative','v22SpecSampling'])];
